const body = ($input.first().json && $input.first().json.body) || $input.first().json || {};
const brief = {
  vertical: body['target_vertical'] || 'Large-scale lithium, copper, and iron ore mining operations in Latin America',
  anchor: 'Sociedad Quimica y Minera de Chile (SQM)', // fixed anchor per the assignment; SQM is the benchmark for every account
  goal: 'Book discovery calls with Head of Operations, VP of HSE, or Site Directors',
  angle: 'Autonomous drone inspection replacing contracted crews at hazardous, 24/7 extraction sites',
  max_accounts: 3,
  contacts_per_account: 2,
  target_titles: ['Head of Operations / VP Operations / Gerente de Operaciones', 'VP HSE / Head of HSE / Gerente HSE', 'Site Director / Site General Manager / Gerente General de Faena', 'Digital Transformation Lead / Head of Innovation / Chief Technology Officer / Gerente de Transformacion Digital'],
  proof_customers: ['Shell', 'Anglo American', 'CSX'],
  suppression: ['Anglo American', 'Shell', 'CSX', 'Airbus', 'Dole', 'Statnett'],
  // >>> EDIT THIS to your real full name + title. It is used verbatim in the signature (no placeholders).
  sender_name: 'Manas Jaiswal',
  sender_title: 'Business Development, FlytBase'
};
return [{ json: brief }];

// Input is now the Build Brief object (the ICP-Research GPT call was removed).
// We derive the ICP inline from the anchor + brief, then fan out one web-search
// prompt per commodity segment.
const j = $input.first().json;
const known = ['lithium', 'copper', 'iron ore'];
let segments = known.filter(s => j.vertical.toLowerCase().includes(s));
if (!segments.length) segments = [j.vertical];
const icp = `Anchor company (ICP benchmark): ${j.anchor}
Target vertical: ${j.vertical}
What FlytBase sells: ${j.angle}
We want to book: ${j.goal}
An ideal account resembles the anchor in scale, hazardous / 24-7 operations, Latin American geography, and reliance on contracted inspection crews.`;
return segments.map(seg => ({ json: { segment: seg, prompt: `Using this ICP:\n${icp}\n\nSearch the web and list 5-6 REAL ${seg} mining companies with major operations in Latin America that resemble this profile in scale, operations, and geography. For each give: HQ country, named Latin American operating sites, one verifiable scale figure (annual production, revenue, or workforce), evidence of 24/7 or hazardous operations, and recent expansion or technology signals. Only include companies you can support with real sources. Exclude ${j.suppression.join(', ')} as primary targets, but note joint ventures involving them.` } }));

const b = $('Build Brief').first().json;
const texts = [];
const sources = [];
for (const item of $input.all()) {
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  texts.push(parts.map(c => c.text || '').join(''));
  for (const a of parts.flatMap(c => c.annotations || [])) if (a.type === 'url_citation' && a.url) sources.push(a.url);
}
const finder_sources = [...new Set(sources)];
const schema = { type: 'object', additionalProperties: false, required: ['accounts'], properties: { accounts: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['company', 'domain', 'hq_country', 'latam_sites', 'commodity', 'scale_evidence', 'ops_evidence', 'why_fit_vs_anchor', 'icp_score', 'ownership_flags', 'sources'], properties: { company: { type: 'string' }, domain: { type: 'string' }, hq_country: { type: 'string' }, latam_sites: { type: 'string' }, commodity: { type: 'string' }, scale_evidence: { type: 'string' }, ops_evidence: { type: 'string' }, why_fit_vs_anchor: { type: 'string' }, icp_score: { type: 'integer' }, ownership_flags: { type: 'string' }, sources: { type: 'array', items: { type: 'string' } } } } } } };
const prompt = `Extract every company from the research below into the JSON schema. icp_score 1-10 = similarity to the anchor company ${b.anchor} (scale 40%, hazard and 24/7 operations 30%, geography 20%, technology-adoption signals 10%). Set latam_sites to the company's named Latin American operating site(s) with country (e.g. "Escondida, Chile; Collahuasi, Chile"); empty string if the research names none. Set ownership_flags to a short note if any of [${b.suppression.join(', ')}] owns or part-owns the company, else an empty string. Set domain to the company's official primary website domain (e.g. sqm.com), lowercase, no protocol or path; empty string if you cannot verify it. For each company, set "sources" to the URL(s) from the SOURCE URLS list below that back up its scale or operations claims; use ONLY URLs from that list, never invent a URL, and use an empty array if none clearly apply. Use an empty string for any unknown text field.\n\nRESEARCH:\n${texts.join('\n\n---\n\n')}\n\nSOURCE URLS (use only these in "sources"):\n${finder_sources.map(u => '- ' + u).join('\n') || '(none returned)'}`;
return [{ json: { ...b, prompt, schema, finder_sources } }];

const prev = $('Merge Finder Results').first().json;
const parts = ($input.first().json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
const text = parts.map(c => c.text || '').join('');
let data;
try { data = JSON.parse(text); } catch (e) { throw new Error('Account JSON parse failed: ' + text.slice(0, 300)); }
let accounts = data.accounts || [];
if (!accounts.length) throw new Error('No accounts extracted - inspect the Structure Accounts node output');

const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const normDom = s => String(s || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '').trim();

const suppressed = (prev.suppression || []).map(norm).filter(Boolean);
accounts = accounts.filter(a => {
  const name = norm(a.company);
  return !suppressed.some(s => name.includes(s));
});
if (!accounts.length) throw new Error('All candidate accounts were suppressed (existing customers) - broaden the search or check the suppression list');

const keyOf = a => normDom(a.domain) || norm(a.company);
const uniq = new Map();
for (const a of accounts) {
  const k = keyOf(a);
  if (!k) continue;
  const cur = uniq.get(k);
  if (!cur || (Number(a.icp_score) || 0) > (Number(cur.icp_score) || 0)) uniq.set(k, a);
}

const LATAM = ['chile', 'peru', 'brazil', 'brasil', 'argentina', 'mexico', 'méxico', 'colombia', 'bolivia', 'ecuador', 'venezuela', 'guatemala', 'panama', 'uruguay', 'paraguay'];
const geoOk = a => {
  if (String(a.latam_sites || '').trim()) return true;
  const blob = (String(a.ops_evidence || '') + ' ' + String(a.scale_evidence || '') + ' ' + String(a.hq_country || '')).toLowerCase();
  return LATAM.some(c => blob.includes(c));
};

let all = [...uniq.values()].map(a => ({ ...a, geo_ok: geoOk(a) }));
all.sort((a, b) => (Number(b.geo_ok) - Number(a.geo_ok)) || ((Number(b.icp_score) || 0) - (Number(a.icp_score) || 0)));
const out = all.slice(0, prev.max_accounts);
if (!out.length) throw new Error('No accounts extracted after filtering - inspect the Structure Accounts node output');
const brief = { anchor: prev.anchor, vertical: prev.vertical, goal: prev.goal, angle: prev.angle, target_titles: prev.target_titles, proof_customers: prev.proof_customers, suppression: prev.suppression, contacts_per_account: prev.contacts_per_account };
return out.map(a => ({ json: { brief, account: a, finder_sources: prev.finder_sources } }));

const prior = $('Build Research Prompt').all();
return $input.all().map((item, i) => {
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  const text = parts.map(c => c.text || '').join('');
  const sources = [...new Set(parts.flatMap(c => c.annotations || []).filter(a => a.type === 'url_citation').map(a => a.url).filter(Boolean))];
  const j = prior[i].json;
  return { json: { brief: j.brief, account: j.account, research_text: text, research_sources: sources } };
});

const schema = { type: 'object', additionalProperties: false, required: ['company', 'recent_news', 'operational_footprint', 'tech_or_expansion_signals', 'hazard_and_247_context', 'contracted_crew_context', 'best_hook', 'best_hook_source', 'sources'], properties: { company: { type: 'string' }, recent_news: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['date', 'item', 'source_url'], properties: { date: { type: 'string' }, item: { type: 'string' }, source_url: { type: 'string' } } } }, operational_footprint: { type: 'string' }, tech_or_expansion_signals: { type: 'array', items: { type: 'string' } }, hazard_and_247_context: { type: 'string' }, contracted_crew_context: { type: 'string' }, best_hook: { type: 'string' }, best_hook_source: { type: 'string' }, sources: { type: 'array', items: { type: 'string' } } } };
return $input.all().map(({ json: j }) => ({ json: { ...j, schema, prompt: `Convert this research into the JSON schema. Each recent_news entry needs three fields: date (YYYY-MM, or "unknown"), item (the headline or fact), and source_url from the SOURCE URLS list. best_hook = the single strongest personalization signal for a cold email to an operations or HSE leader. Set best_hook_source to the ONE url from the SOURCE URLS list that backs that hook. Set "sources" to the url(s) from the SOURCE URLS list that back this brief. Use ONLY urls from the SOURCE URLS list, never invent one; leave a url empty if none clearly applies. Use an empty string or empty list for anything unknown.

RESEARCH ON ${j.account.company}:
${j.research_text}

SOURCE URLS (use only these):
${j.research_sources.join('
')}` } }));

const prior = $('Build Research Structuring Prompt').all();
return $input.all().map((item, i) => {
  const j = prior[i].json;
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  const text = parts.map(c => c.text || '').join('');
  let rb;
  try { rb = JSON.parse(text); } catch (e) { rb = { company: j.account.company, best_hook: '', parse_error: text.slice(0, 300) }; }
  return { json: { brief: j.brief, account: j.account, research: rb, research_sources: j.research_sources } };
});

const prior = $('Build Exec Search Prompt').all();
return $input.all().map((item, i) => {
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  const text = parts.map(c => c.text || '').join('');
  const j = prior[i].json;
  return { json: { ...j, exec_text: text } };
});

const prior = $('Build Tavily Request').all();
return $input.all().map((item, i) => {
  const j = prior[i].json;
  const li_results = (item.json.results || []).map(r => ({ title: r.title, url: r.url, snippet: (r.content || '').slice(0, 300) }));
  return { json: { ...j, li_results, li_source: 'tavily' } };
});

const schema = { type: 'object', additionalProperties: false, required: ['contacts'], properties: { contacts: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['name', 'title', 'seniority', 'role_match', 'linkedin_url', 'evidence_source', 'notes'], properties: { name: { type: 'string' }, title: { type: 'string' }, seniority: { type: 'string' }, role_match: { type: 'string', enum: ['operations', 'hse', 'site', 'digital_transformation', 'other'] }, linkedin_url: { type: 'string' }, evidence_source: { type: 'string' }, notes: { type: 'string' } } } } } };
return $input.all().map(({ json: j }) => {
  const li = (j.li_results || []).map(r => `${r.title} | ${r.url} | ${r.snippet}`).join('
');
  return { json: { ...j, schema, prompt: `Merge these findings into a contact list for ${j.account.company}.

STRICT RULES:
1. SOURCE: include a person ONLY if a source URL supports their name AND role; put that URL in evidence_source. Never invent anyone.
2. ROLE FIT: include a person ONLY if their role maps to one of these families - operations leadership (Head/VP/Director of Operations, Gerente de Operaciones), HSE/safety leadership (VP/Head/Director of HSE, SSMA, Safety), site leadership (Site Director, General Manager, Gerente General de Faena), or digital transformation leadership (Digital Transformation Lead, Head of Innovation, CTO, Gerente de Transformacion Digital). Set role_match to "operations", "hse", "site", or "digital_transformation" accordingly. If a well-sourced person does NOT fit these families, set role_match to "other" (it will be filtered out).
3. Do not include email addresses. Use an empty string for any unknown field.
4. Return at most ${j.brief.contacts_per_account} people who FIT the families above; return an empty list if none are both verifiable and role-fitting.

TARGET TITLES: ${j.brief.target_titles.join('; ')}

WEB RESEARCH FINDINGS:
${j.exec_text}

LINKEDIN SEARCH RESULTS (source: ${j.li_source}; title | url | snippet):
${li || '(none found)'}` } };
});

const prior = $('Build Contacts Prompt').all();
const out = [];
const FIT = new Set(['operations', 'hse', 'site', 'digital_transformation']);
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const normName = s => String(s || '').toLowerCase().replace(/[^a-z\s]/g, '').replace(/\s+/g, ' ').trim();
const liHandle = s => { const m = String(s || '').toLowerCase().match(/linkedin\.com\/in\/([^\/?#]+)/); return m ? m[1] : ''; };
const isProfile = s => /linkedin\.com\/in\//i.test(String(s || ''));

function siteScore(contact, account) {
  const sites = norm(account.latam_sites || '');
  if (!sites) return 0;
  const siteWords = sites.split(' ').filter(w => w.length > 3);
  const hay = norm((contact.title || '') + ' ' + (contact.notes || ''));
  return siteWords.some(w => hay.includes(w)) ? 1 : 0;
}

function pickDiverse(contacts, n, account) {
  const scored = contacts.map(c => ({ c, site: siteScore(c, account) })).sort((a, b) => b.site - a.site);
  const picked = [];
  const usedRoles = new Set();
  for (const { c } of scored) {
    if (picked.length >= n) break;
    const role = String(c.role_match || '').toLowerCase();
    if (!usedRoles.has(role)) { picked.push(c); usedRoles.add(role); }
  }
  if (picked.length < n) {
    for (const { c } of scored) {
      if (picked.length >= n) break;
      if (!picked.includes(c)) picked.push(c);
    }
  }
  return picked;
}

$input.all().forEach((item, i) => {
  const j = prior[i].json;
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  const text = parts.map(c => c.text || '').join('');
  let contacts = [];
  try { contacts = JSON.parse(text).contacts || []; } catch (e) { }
  contacts = contacts.filter(c => FIT.has(String(c.role_match || '').toLowerCase()));
  const seen = new Set();
  contacts = contacts.filter(c => { const k = liHandle(c.linkedin_url) || normName(c.name); if (!k || seen.has(k)) return false; seen.add(k); return true; });
  contacts = contacts.map(c => ({ ...c, linkedin_valid: isProfile(c.linkedin_url) }));
  contacts = pickDiverse(contacts, j.brief.contacts_per_account, j.account);
  if (!contacts.length) {
    out.push({ json: { found: false, company: j.account.company, reason: 'No verifiable, role-fitting contact (Operations / HSE / Site / Digital Transformation leadership) surfaced by web search + LinkedIn lookup' } });
  } else {
    for (const c of contacts) out.push({ json: { found: true, brief: j.brief, account: j.account, research: j.research, research_sources: j.research_sources, contact: c } });
  }
});
return out;

const ANGLES = [
  'save money (cut the cost of contracted inspection crews, rework and mobilisation)',
  'protect revenue (avoid downtime, keep 24/7 extraction running)',
  'save time (faster, more frequent inspections without mobilising a crew)',
  'raise their standing (be the safety and innovation leader at hazardous sites)',
  'keep people safe (get workers out of hazardous zones at 24/7 faces)'
];
const SUBJECT_STYLES = [
  'SMYKM style: join 2-3 specifics with " + " built from a real research signal plus FlytBase, e.g. "Escondida + 24/7 Inspections + FlytBase". Cryptic to a stranger, obvious to them.',
  'a specific outcome/value hook tied to their site, e.g. "Fewer crew hours at <named site>"',
  'a short, specific curiosity question about their operation (no clickbait)',
  'a plain, direct subject naming their site or project plus the topic'
];
const TRANSITIONS = [
  'You may use a "the real reason I am reaching out is..." pivot.',
  'Use a different natural segue of your own; do NOT use the phrase "the real reason".',
  'Skip an explicit transition; let the second sentence flow straight into the point.'
];

const PROOF_LIBRARY = {
  anglo_american: {
    name: 'Anglo American',
    line: 'At their Quellaveco copper mine in Peru, Anglo American eliminated truck-based topographic surveying across mountainous terrain and got crews out of hazardous field positions using the same drone-in-a-box approach.',
    keywords: ['tailings', 'pit wall', 'stockpile', 'terrain', 'survey', 'geotechnical', 'dam', 'open pit', 'open-pit', 'waste rock', 'slope']
  },
  sqm: {
    name: 'SQM',
    line: 'SQM used the same dock-based drone approach to cut inspection cycles at their Chilean operation from two to three weeks down to three to four hours, a 4x improvement in extraction yield.',
    keywords: ['leach', 'leaching', 'irrigation', 'sprinkler', 'heap', 'brine', 'evaporation pond', 'lithium']
  },
  csx: {
    name: 'CSX',
    line: 'CSX uses the same autonomous drone approach to catch rail defects down to an eighth of an inch without sending crews into active yards.',
    keywords: ['rail', 'railway', 'railroad', 'track', 'logistics', 'port', 'yard']
  },
  shell: {
    name: 'Shell',
    line: 'Shell replaced twice-weekly manual tank inspections at their Rotterdam refinery with the same autonomous drone-in-a-box system, running with extremely little downtime.',
    keywords: ['refinery', 'tank', 'smelter', 'processing plant', 'chemical plant', 'atex']
  }
};
function pickProof(research) {
  const r = research || {};
  const hay = [r.hazard_and_247_context, r.contracted_crew_context, r.operational_footprint, r.best_hook, ...((r.tech_or_expansion_signals || []))]
    .filter(Boolean).join(' ').toLowerCase();
  for (const key of ['sqm', 'csx', 'shell']) {
    if (PROOF_LIBRARY[key].keywords.some(k => hay.includes(k))) return PROOF_LIBRARY[key];
  }
  return PROOF_LIBRARY.anglo_american;
}

return $input.all().map(({ json: j }, i) => {
  const b = $('Build Brief').first().json;
  const proof = pickProof(j.research);
  const SENDERS = [
    { name: b.sender_name || 'Manas Jaiswal', title: b.sender_title || 'Business Development, FlytBase' },
    { name: 'Lucas Marcus', title: 'Business Development, FlytBase' },
    { name: 'Sofia Reyes', title: 'Business Development, FlytBase' },
    { name: 'Diego Alvarez', title: 'Business Development, FlytBase' }
  ];
  const sender = SENDERS[i % SENDERS.length];
  const senderName = sender.name;
  const senderTitle = sender.title;
  const firstName = String(j.contact.name || '').trim().split(/\s+/)[0] || j.contact.name;
  const angle = ANGLES[i % ANGLES.length];
  const subjectStyle = SUBJECT_STYLES[i % SUBJECT_STYLES.length];
  const transition = TRANSITIONS[i % TRANSITIONS.length];
  const prompt = `You are ${senderName}, a business development rep at FlytBase (a hunter) writing ONE cold outbound email using "Show Me You Know Me" (SMYKM) principles. Write like a sharp human who did their homework and holds a point of view, not a tool.\n\nRECIPIENT: ${j.contact.name}, ${j.contact.title} at ${j.account.company}\nRESEARCH BRIEF (verified facts, use ONLY these): ${JSON.stringify(j.research)}\nBEST HOOK: ${j.research.best_hook}\nFLYTBASE: autonomous drone-in-a-box inspection replacing contracted crews at hazardous 24/7 industrial sites; 300+ enterprise sites in 40+ countries.\nPROOF POINT (use this exact real result, do not invent a different one): ${proof.line}\n\nVARIETY CONTROLS FOR THIS EMAIL (make each email in the batch distinct; do NOT fall back to a fixed template):\n- Lead value angle: ${angle}.\n- Subject line style: ${subjectStyle}\n- Transition: ${transition}\n\nPRINCIPLES (guidance, not a rigid script; the cheat sheet is one reference, there are many valid shapes):\n- SUBJECT: specific to THIS person, meaningless to a stranger. Never generic like "Drone inspection for ${j.account.company}".\n- FIRST SENTENCE: no niceties ("hope this finds you well"), no instant pitch. Open on the specific research signal, in your own voice.\n- BODY: name the challenge this person owns given their title (${j.contact.title}); make a confident case that leaning on contracted crews to inspect hazardous 24/7 sites is slow, costly and risky, and autonomous inspection is the better move. Frame it around the lead value angle above. Weave in the PROOF POINT above ONLY if it strengthens the point, using the exact real result given, never invent a different statistic or a different customer. Pre-empt their most likely objection in one line.\n- CLOSE: a considerate CTA with a BROAD timeframe that works around THEIR calendar. NEVER propose a specific day/time, never attach a calendar link, never say "book a demo". (Bad example to avoid: "Does 3PM EST Thursday work for you?")\n\nSTANCE + VOICE:\n- Take a side, be persuasive, do not hedge with might/could/perhaps, do not present both sides.\n- Conversational and human. Confident, not arrogant or salesy.\n\nHARD RULES:\n- Use ONLY facts from the research brief and the PROOF POINT given. Never invent a site, figure, person, event, customer name, or statistic.\n- Be CONCISE: aim 70-120 words. Cut any sentence that does not earn its place. Do not pad to sound senior.\n- No bullet lists. No exclamation marks. No buzzwords (revolutionary, cutting-edge, synergy, game-changer).\n- NO em dashes (the "—" character). Use commas or periods. No en dashes as separators.\n- Sign off with the REAL name below, never a bracketed placeholder like [name] or {company}.\n\nFORMATTING (match the cheat-sheet layout, this matters):\n- Begin with a greeting on its own line: "Hi ${firstName}," then a blank line.\n- Break the body into SHORT, SEPARATE paragraphs with ONE BLANK LINE between each: (1) the opener on the specific signal, (2) the transition into the point plus the challenge they own, (3) the value plus the proof point plus the objection pre-empt, (4) the close. You may merge two only if it clearly reads better, but never return one dense block.\n- Then a blank line, a sign-off word ("Cheers," or "Best,"), the sender name on the next line, and the title on the line after.\n- Use real line breaks. A blank line means two newlines.\n\nOUTPUT FORMAT (use real line breaks exactly like this, blank line between every paragraph):\nSubject: <subject>\n\nHi ${firstName},\n\n<opening paragraph on the specific signal>\n\n<transition + the challenge they own>\n\n<the value + the proof point + the objection pre-empt>\n\n<the close: broad, considerate CTA>\n\nCheers,\n${senderName}\n${senderTitle}`;
  return { json: { ...j, prompt, writer_prompt: prompt, style_angle: angle, proof_used: proof.name } };
});

const prior = $('Build Writer Prompt').all();
return $input.all().map((item, i) => {
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  const email = parts.map(c => c.text || '').join('').trim();
  return { json: { ...prior[i].json, email_draft: email } };
});

const prior = $('Build Critic Prompt').all();
return $input.all().map((item, i) => {
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  const text = parts.map(c => c.text || '').join('');
  let v;
  try { v = JSON.parse(text); } catch (e) { v = { passed: false, failures: ['critic output parse error'] }; }
  return { json: { ...prior[i].json, verdict: v } };
});

return $input.all().map(({ json: j }) => ({ json: { ...j, prompt: `${j.writer_prompt}

REVISE: a previous draft failed quality review for these reasons: ${j.verdict.failures.join('; ')}.
Previous draft:
${j.email_draft}

Write an improved email that fixes every failure and obeys every hard rule.` } }));

const prior = $('Build Rewrite Prompt').all();
return $input.all().map((item, i) => {
  const parts = (item.json.output || []).filter(o => o.type === 'message').flatMap(m => m.content || []).filter(c => c.type === 'output_text');
  const email = parts.map(c => c.text || '').join('').trim();
  return { json: { ...prior[i].json, email_first_draft: prior[i].json.email_draft, email_final: email, rewritten: true } };
});

const emails = $input.all().filter(i => i.json.account).map(({ json: j }) => ({
  company: j.account.company,
  contact_name: j.contact.name,
  contact_title: j.contact.title,
  linkedin_url: j.contact.linkedin_url || '',
  evidence_source: j.contact.evidence_source || '',
  contact_email: j.contact.email || '',
  email_status: j.contact.email_status || '',
  email_source: j.contact.email_source || '',
  email_confidence: j.contact.email_confidence,
  email_verified_status: j.contact.email_verified_status || '',
  email_deliverable: !!j.contact.email_deliverable,
  company_domain: j.contact.company_domain || (j.account.domain || ''),
  email: j.email_final,
  rewritten_after_critic: j.rewritten,
  critic_verdict: j.verdict,
  signal_used: j.research.best_hook,
  research_sources: j.research_sources
}));
let accounts = [];
