// ============================================================================
//  EMAIL RESOLVER + VERIFIER — free waterfall. GPT never invents an email;
//  this node attaches a REAL, verified address (fabrication-safe).
//  Order (credit-optimised):
//    1) account.domain (from Stage 1) -> Prospeo becomes PRIMARY (75 free/mo).
//    2) If no domain, Hunter Domain Search resolves it (cached, 1/company).
//    3) Prospeo Email Finder  -> primary per-contact resolver.
//    4) Hunter Email Finder   -> last-resort fallback.
//    5) Hunter Email Verifier -> deliverability check (set VERIFY=false to save credits).
// ============================================================================
// API KEYS — replace locally. DO NOT commit real keys. (Or set n8n env vars.)
const keys = {
  prospeo: '<<PROSPEO_API_KEY>> ',
  hunter:  '<<HUNTER_API_KEY>>',
};
const VERIFY = true; // set false to skip verification and conserve Hunter credits
const usable = k => k && !String(k).startsWith('<<');
const norm   = s => String(s || '').toLowerCase();

const http = async (opts) => {
  try { return await this.helpers.httpRequest({ json: true, timeout: 20000, ...opts }); }
  catch (e) { return { __error: (e && e.message) || String(e) }; }
};

const domainCache = {};
async function resolveDomain(company, accountDomain) {
  if (accountDomain) return { domain: accountDomain, emails: [] };      // Stage-1 domain wins
  if (domainCache[company] !== undefined) return domainCache[company];
  let out = { domain: '', emails: [] };
  if (usable(keys.hunter) && company) {
    const r = await http({ method: 'GET', url: 'https://api.hunter.io/v2/domain-search',
      qs: { company, api_key: keys.hunter, limit: 25 } });
    if (r && r.data) out = { domain: r.data.domain || '', emails: r.data.emails || [] };
  }
  domainCache[company] = out;
  return out;
}

function fromHunterDomain(emails, first, last, title) {
  const lc = norm(last), fc = norm(first);
  const tw = norm(title).split(/\s+/).filter(word => word.length > 3);
  let best = null;
  for (const e of emails) {
    const eln = norm(e.last_name), efn = norm(e.first_name);
    const pos = norm(e.position) + ' ' + norm(e.department);
    if (lc && eln && eln === lc) { best = e; break; }
    if (!best && fc && efn && efn === fc) best = e;
    if (!best && tw.some(word => pos.includes(word))) best = e;
  }
  return best ? { email: best.value, source: 'hunter_domain_search',
    confidence: (best.confidence != null ? best.confidence : null), status: 'from_domain_index' } : null;
}

async function fromProspeo(first, last, domain) {
  if (!usable(keys.prospeo) || !domain) return null;
  const r = await http({ method: 'POST', url: 'https://api.prospeo.io/email-finder',
    headers: { 'Content-Type': 'application/json', 'X-KEY': keys.prospeo },
    body: { first_name: first, last_name: last, company: domain } });
  // Defensive parse — confirm exact field names against Prospeo's current docs.
  const resp  = (r && r.response) ? r.response : r;
  const email = resp && (resp.email && resp.email.email ? resp.email.email : resp.email);
  const status = resp && (resp.email_status ||
    (resp.email && resp.email.verification && resp.email.verification.status));
  return (email && typeof email === 'string') ? { email, source: 'prospeo', confidence: null, status: status || 'prospeo' } : null;
}

async function fromHunterFinder(first, last, domain) {
  if (!usable(keys.hunter) || !domain) return null;
  const r = await http({ method: 'GET', url: 'https://api.hunter.io/v2/email-finder',
    qs: { domain, first_name: first, last_name: last, api_key: keys.hunter } });
  const email = r && r.data && r.data.email;
  return email ? { email, source: 'hunter_email_finder',
    confidence: (r.data.score != null ? r.data.score : null), status: 'hunter' } : null;
}

async function verifyHunter(email) {
  if (!VERIFY || !usable(keys.hunter) || !email) return null;
  const r = await http({ method: 'GET', url: 'https://api.hunter.io/v2/email-verifier',
    qs: { email, api_key: keys.hunter } });
  return (r && r.data) ? { status: r.data.status, result: r.data.result, score: r.data.score } : null;
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const contact = { ...(j.contact || {}) };
  const nameParts = String(contact.name || '').trim().split(/\s+/);
  const first = nameParts[0] || '';
  const last  = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';
  const company = (j.account && j.account.company) || '';
  const accountDomain = (j.account && (j.account.domain || j.account.website)) || '';

  const dom = await resolveDomain(company, accountDomain);
  const domain = dom.domain || '';

  let hit = null;
  if (dom.emails && dom.emails.length) hit = fromHunterDomain(dom.emails, first, last, contact.title);
  if (!hit) hit = await fromProspeo(first, last, domain);
  if (!hit) hit = await fromHunterFinder(first, last, domain);

  const verification = hit ? await verifyHunter(hit.email) : null;

  contact.company_domain       = domain;
  contact.email                = hit ? hit.email : '';
  contact.email_source         = hit ? hit.source : '';
  contact.email_confidence     = hit ? hit.confidence : null;
  contact.email_status         = hit ? hit.status : 'not_found';
  contact.email_verified_status = verification ? (verification.status || verification.result || '') : '';
  contact.email_deliverable    = verification
    ? (verification.result === 'deliverable' || verification.status === 'valid')
    : false;
  contact.verify_before_send   = !(contact.email_deliverable);

  out.push({ json: { ...j, contact } });
}
