// Deterministic em/en dash remover. Runs AFTER the critic + rewrite loop, so no em dash can
// survive into the final email regardless of what the model did. Prompt instructions alone
// never fully eliminate this, this guarantees it.
function deDash(s) {
  if (s == null) return s;
  return String(s)
    .replace(/\s*[—–―]\s*/g, ', ')
    .replace(/\s+,/g, ',')
    .replace(/,\s*,/g, ',')
    .replace(/,\s*\./g, '.')
    .replace(/[ \t]{2,}/g, ' ');
}
return $input.all().map(({ json: j }) => {
  const out = { ...j };
  if (out.email_final) out.email_final = deDash(out.email_final);
  return { json: out };
});
